#include <bits/stdc++.h>
using namespace std;
const int INF = 0x7f7f7f7f;
int n,m,s,t,p,c,d,x[505],y[505];
int total_flow, total_cost;
int edge_idx=1, head[5000005], next_edge[10000010], to_node[10000010], capacity[10000010], cost_edge[10000010];
int dist[5000005], parent[5000005], last_edge[5000005], flow[5000005];
bool in_queue[5000005];

void addEdge(int u, int v, int cap, int cst) {
    next_edge[++edge_idx] = head[u];
    to_node[edge_idx] = v;
    capacity[edge_idx] = cap;
    cost_edge[edge_idx] = cst;
    head[u] = edge_idx;
}

bool spfa() {
    memset(dist, 0x7f, sizeof(dist));
    memset(in_queue, false, sizeof(in_queue));
    queue<int> q;
    q.push(s);
    in_queue[s] = true;
    dist[s] = 0;
    flow[s] = INT_MAX;
    parent[t] = -1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = false;
        for (int i = head[u]; i; i = next_edge[i]) {
            if (capacity[i] && dist[to_node[i]] > dist[u] + cost_edge[i]) {
                dist[to_node[i]] = dist[u] + cost_edge[i];
                parent[to_node[i]] = u;
                last_edge[to_node[i]] = i;
                flow[to_node[i]] = min(flow[u], capacity[i]);
                if (!in_queue[to_node[i]]) {
                    in_queue[to_node[i]] = true;
                    q.push(to_node[i]);
                }
            }
        }
    }
    return parent[t] != -1;
}

void minCostFlow() {
    total_flow = total_cost = 0;
    while (spfa()) {
        int current = t;
        total_flow += flow[t];
        total_cost += flow[t] * dist[t];
        while (current != s) {
            capacity[last_edge[current]] -= flow[t];
            capacity[last_edge[current] ^ 1] += flow[t];
            current = parent[current];
        }
    }
}

int node_id(int layer, int node) {
    return layer * n + node;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> p >> c >> d;
    s = 0;
    t = n * 99 + 1;
    for (int i=1, x; i<=p && cin>>x; i++) {
        addEdge(s, node_id(0,x), 1, 0);
        addEdge(node_id(0,x), s, 0, 0);
    }
    for (int i=1; i<=m; i++) {
        cin>>x[i]>>y[i];
    }
    for (int i=0; i<=99; i++) {
        addEdge(node_id(i,1), node_id(i+1,1), INF, 0);
        addEdge(node_id(i+1,1), node_id(i,1), 0, 0);
        for (int j=2; j<=n; j++) {
            addEdge(node_id(i,j), node_id(i+1,j), INF, c);
            addEdge(node_id(i+1,j), node_id(i,j), 0, -c);
        }
        for (int j=1; j<=m; j++) {
            for (int k=1; k<=p; k++) {
                int cst = d*k*k - d*(k-1)*(k-1) + c;
                addEdge(node_id(i,x[j]), node_id(i+1,y[j]), 1, cst);
                addEdge(node_id(i+1,y[j]), node_id(i,x[j]), 0, -cst);
                addEdge(node_id(i,y[j]), node_id(i+1,x[j]), 1, cst);
                addEdge(node_id(i+1,x[j]), node_id(i,y[j]), 0, -cst);
            }
        }
    }
    minCostFlow();
    cout << total_cost << "\n";
    return 0;
}
